  pd(s) { if (!s) return null; const p = String(s).split('/'); return p.length < 3 ? null : new Date(+p[0], +p[1] - 1, +p[2]); }
  md(d) { return d ? (d.getMonth() + 1) + '/' + d.getDate() : ''; }
