    // 對方文件 §11：state 只能用一次（上面已從 sessionStorage 刪掉）且要有期限；超過 15 分鐘就請使用者重來
    if (!pend.at || Date.now() - pend.at > 15 * 60000) throw new Error('授權逾時，請重新連結一次');
