      if (H.length) t.push('持有指定稱號且該角色當隊長 +' + Math.max.apply(null, H.map(x => x.bonusRate || 0)) + '%（' + H.length + ' 種稱號）');
      if (S) t.push('單張卡技能倍率上限 ' + S.scoreUpRateLimit + '%' + (S.scoreUpRateLimit >= 300 ? '（等於不設限）' : ''));
