              rar: RN[r.rar] || '？', ms: 'MR' + r.mr + '　SLv.' + r.sl,
              bonus: r.bonus == null ? '—' : ('＋' + r.bonus.toFixed(1) + '%'),
              tag: r.why ? r.why : (used ? '已列入後排' : '加成不足，未入選'),
              tagBg: r.why ? '#8c8c96' : (used ? 'var(--accent)' : 'rgba(0,0,0,.35)'),
              bd: r.unsure ? '#c98a2b' : (used ? 'var(--accent)' : 'var(--border)'),
              warn: r.unsure ? '待確認' : '',
